-- VERIFICACION FINAL (solo lectura): postcheck de 15 comprobaciones + contrato exacto de las 4 tablas y 2 triggers
-- Base de datos: u611730801_Plataforma (referencias explicitas; NO depende de USE ni de la base seleccionada en phpMyAdmin).
-- VERIFICACION DE SOLO LECTURA: no modifica nada. Cada fila debe decir OK (o ser informativa). Cualquier DETENER: no continuar.
-- Resultado esperado: todo OK; las filas "empresas sin contador completo" y "siguientes numeros ya en uso" deben decir 0.
--

SELECT 'canecas_secuencias existe' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_secuencias')=1, 'OK', 'DETENER') AS resultado;
SELECT 'direccion_entrega VARCHAR(500) NULL' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas' AND COLUMN_NAME='direccion_entrega' AND COLUMN_TYPE='varchar(500)' AND IS_NULLABLE='YES')=1, 'OK', 'DETENER') AS resultado;
SELECT 'ventas con direccion de entrega' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_ventas WHERE direccion_entrega IS NOT NULL;
SELECT 'chk_can_venta_direccion presente' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TABLE_CONSTRAINTS WHERE CONSTRAINT_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_ventas' AND CONSTRAINT_NAME='chk_can_venta_direccion')=1, 'OK', 'DETENER') AS resultado;
SELECT 'activo_unico virtual presente' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos' AND COLUMN_NAME='activo_unico' AND EXTRA LIKE '%VIRTUAL%')=1, 'OK', 'DETENER') AS resultado;
SELECT 'uq_can_producto_activo_unico unico sobre (empresa_id,activo_unico)' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_productos' AND INDEX_NAME='uq_can_producto_activo_unico' AND NON_UNIQUE=0)=2, 'OK', 'DETENER') AS resultado;
SELECT 'trigger de ventas: 2 y el de actualizacion protege direccion_entrega' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND EVENT_OBJECT_TABLE='canecas_ventas')=2 AND (SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND ACTION_STATEMENT LIKE '%direccion_entrega%')=1, 'OK', 'DETENER') AS resultado;
SELECT 'ninguna empresa con mas de una caneca activa' AS verificacion, IF((SELECT COUNT(*) FROM (SELECT empresa_id FROM `u611730801_Plataforma`.canecas_productos WHERE activo=1 GROUP BY empresa_id HAVING COUNT(*)>1) t)=0, 'OK', 'DETENER') AS resultado;
SELECT 'contadores no menores que el maximo historico' AS verificacion, IF((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_secuencias s JOIN (SELECT empresa_id, 'COMPRA' AS tipo, MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(referencia)), '^COMP[ _-]?', '') AS UNSIGNED)) AS maximo FROM `u611730801_Plataforma`.canecas_compras WHERE UPPER(TRIM(referencia)) REGEXP '^COMP[ _-]?[0-9]{1,15}$' GROUP BY empresa_id UNION ALL SELECT empresa_id, 'VENTA', MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(documento)), '^VTA[ _-]?', '') AS UNSIGNED)) FROM `u611730801_Plataforma`.canecas_ventas WHERE UPPER(TRIM(documento)) REGEXP '^VTA[ _-]?[0-9]{1,15}$' GROUP BY empresa_id UNION ALL SELECT empresa_id, 'PRODUCTO', MAX(CAST(REGEXP_REPLACE(UPPER(TRIM(codigo)), '^CAN[ _-]?', '') AS UNSIGNED)) FROM `u611730801_Plataforma`.canecas_productos WHERE UPPER(TRIM(codigo)) REGEXP '^CAN[ _-]?[0-9]{1,15}$' GROUP BY empresa_id) h ON h.empresa_id=s.empresa_id AND h.tipo=s.tipo WHERE s.ultimo < h.maximo)=0, 'OK', 'DETENER') AS resultado;
SELECT 'empresas sin contador completo' AS verificacion, CAST((SELECT COUNT(*) FROM `u611730801_Plataforma`.empresas e WHERE (SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_secuencias s WHERE s.empresa_id=e.id)<>3) AS CHAR) AS resultado;
SELECT 'siguientes numeros ya en uso por un documento' AS verificacion, CAST((SELECT COUNT(*) FROM `u611730801_Plataforma`.canecas_secuencias s WHERE (s.tipo='COMPRA' AND EXISTS (SELECT 1 FROM `u611730801_Plataforma`.canecas_compras c WHERE c.empresa_id=s.empresa_id AND c.referencia=CONCAT('COMP-', LPAD(s.ultimo+1, 6, '0')))) OR (s.tipo='VENTA' AND EXISTS (SELECT 1 FROM `u611730801_Plataforma`.canecas_ventas v WHERE v.empresa_id=s.empresa_id AND v.documento=CONCAT('VTA-', LPAD(s.ultimo+1, 6, '0')))) OR (s.tipo='PRODUCTO' AND EXISTS (SELECT 1 FROM `u611730801_Plataforma`.canecas_productos p WHERE p.empresa_id=s.empresa_id AND p.codigo=CONCAT('CAN-', LPAD(s.ultimo+1, 6, '0'))))) AS CHAR) AS resultado;
SELECT 'ref_auto y doc_auto virtuales con indice unico por empresa' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND ((TABLE_NAME='canecas_compras' AND COLUMN_NAME='ref_auto') OR (TABLE_NAME='canecas_ventas' AND COLUMN_NAME='doc_auto')) AND EXTRA LIKE '%VIRTUAL%')=2 AND (SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND INDEX_NAME IN ('uq_can_compra_ref_auto','uq_can_venta_doc_auto') AND NON_UNIQUE=0)=4, 'OK', 'DETENER') AS resultado;
SELECT 'sin documentos con formato generado duplicados por empresa' AS verificacion, IF((SELECT COUNT(*) FROM (SELECT empresa_id FROM `u611730801_Plataforma`.canecas_compras WHERE ref_auto IS NOT NULL GROUP BY empresa_id, ref_auto HAVING COUNT(*)>1 UNION ALL SELECT empresa_id FROM `u611730801_Plataforma`.canecas_ventas WHERE doc_auto IS NOT NULL GROUP BY empresa_id, doc_auto HAVING COUNT(*)>1) t)=0, 'OK', 'DETENER') AS resultado;
SELECT 'recuento canecas_ventas' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_ventas;
SELECT 'recuento canecas_productos' AS verificacion, CAST(COUNT(*) AS CHAR) AS resultado FROM `u611730801_Plataforma`.canecas_productos;
SELECT 'contrato tablas de canecas_secuencias (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(TABLE_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(ENGINE AS CHAR),'<NULL>'), IFNULL(CAST(TABLE_COLLATION AS CHAR),'<NULL>'), IFNULL(CAST(CREATE_OPTIONS AS CHAR),'<NULL>')) AS x FROM information_schema.TABLES WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_secuencias') h)='bba115928dbe15e2599413701640a209', 'OK', 'DETENER') AS resultado;
