SELECT 'contrato indices de canecas_secuencias (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(INDEX_NAME AS CHAR),'<NULL>'), IFNULL(CAST(NON_UNIQUE AS CHAR),'<NULL>'), IFNULL(CAST(SEQ_IN_INDEX AS CHAR),'<NULL>'), IFNULL(CAST(COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(SUB_PART AS CHAR),'<NULL>'), IFNULL(CAST(INDEX_TYPE AS CHAR),'<NULL>'), IFNULL(CAST(COLLATION AS CHAR),'<NULL>'), IFNULL(CAST(NULLABLE AS CHAR),'<NULL>'), IFNULL(CAST(IGNORED AS CHAR),'<NULL>')) AS x FROM information_schema.STATISTICS WHERE TABLE_SCHEMA='u611730801_Plataforma' AND TABLE_NAME='canecas_secuencias') h)='fb4017149f920bacb117d2d774245db6', 'OK', 'DETENER') AS resultado;
