SELECT 'contrato foraneas de canecas_compras (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(k.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.ORDINAL_POSITION AS CHAR),'<NULL>'), IFNULL(CAST(k.COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.REFERENCED_TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(k.REFERENCED_COLUMN_NAME AS CHAR),'<NULL>'), IFNULL(CAST(r.UPDATE_RULE AS CHAR),'<NULL>'), IFNULL(CAST(r.DELETE_RULE AS CHAR),'<NULL>')) AS x FROM information_schema.KEY_COLUMN_USAGE k JOIN information_schema.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=k.CONSTRAINT_SCHEMA AND r.TABLE_NAME=k.TABLE_NAME AND r.CONSTRAINT_NAME=k.CONSTRAINT_NAME WHERE k.TABLE_SCHEMA='u611730801_Plataforma' AND k.TABLE_NAME='canecas_compras' AND k.REFERENCED_TABLE_NAME IS NOT NULL) h)='70036f652e558defbb48e0b182136505', 'OK', 'DETENER') AS resultado;
SELECT 'contrato checks de canecas_compras (huella exacta)' AS verificacion, IF((SELECT COALESCE(MD5(GROUP_CONCAT(x ORDER BY BINARY x SEPARATOR '~~')), MD5('')) FROM (SELECT CONCAT_WS(0x1f, IFNULL(CAST(t.TABLE_NAME AS CHAR),'<NULL>'), IFNULL(CAST(t.CONSTRAINT_NAME AS CHAR),'<NULL>'), IFNULL(CAST(c.CHECK_CLAUSE AS CHAR),'<NULL>')) AS x FROM information_schema.TABLE_CONSTRAINTS t JOIN information_schema.CHECK_CONSTRAINTS c ON c.CONSTRAINT_SCHEMA=t.CONSTRAINT_SCHEMA AND c.TABLE_NAME=t.TABLE_NAME AND c.CONSTRAINT_NAME=t.CONSTRAINT_NAME WHERE t.CONSTRAINT_SCHEMA='u611730801_Plataforma' AND t.TABLE_NAME='canecas_compras') h)='b85db8ded769e62b31f2a6be4c48815f', 'OK', 'DETENER') AS resultado;
SELECT 'trigger trg_can_venta_bu exacto (tiempo, evento, tabla y cuerpo normalizado)' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bu' AND EVENT_OBJECT_TABLE='canecas_ventas' AND ACTION_TIMING='BEFORE' AND EVENT_MANIPULATION='UPDATE' AND BINARY TRIM(REGEXP_REPLACE(REPLACE(ACTION_STATEMENT, CHAR(13), ''), '[[:space:]]+', ' '))=BINARY 'CREATE OR REPLACE TRIGGER `u611730801_Plataforma`.trg_can_venta_bu BEFORE UPDATE ON `u611730801_Plataforma`.canecas_ventas FOR EACH ROW BEGIN IF NOT (NEW.id <=> OLD.id) OR NOT (NEW.empresa_id <=> OLD.empresa_id) OR NOT (NEW.cliente_id <=> OLD.cliente_id) OR NOT (NEW.producto_id <=> OLD.producto_id) OR NOT (NEW.ubicacion_id <=> OLD.ubicacion_id) OR NOT (NEW.direccion_entrega <=> OLD.direccion_entrega) OR NOT (NEW.fecha_venta <=> OLD.fecha_venta) OR NOT (NEW.documento <=> OLD.documento) OR NOT (NEW.cantidad <=> OLD.cantidad) OR NOT (NEW.precio_unitario_centavos <=> OLD.precio_unitario_centavos) OR NOT (NEW.total_centavos <=> OLD.total_centavos) OR NOT (NEW.costo_centavos <=> OLD.costo_centavos) OR NOT (NEW.moneda <=> OLD.moneda) OR NOT (NEW.salida_id <=> OLD.salida_id) OR NOT (NEW.clave_operacion <=> OLD.clave_operacion) OR NOT (NEW.creado_por <=> OLD.creado_por) OR NOT (NEW.creado_en <=> OLD.creado_en) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''CANECAS_VENTA_INMUTABLE''; END IF; IF OLD.estado = ''ANULADA'' AND (NOT (NEW.estado <=> OLD.estado) OR NOT (NEW.anulada_por <=> OLD.anulada_por) OR NOT (NEW.anulada_en <=> OLD.anulada_en) OR NOT (NEW.motivo_anulacion <=> OLD.motivo_anulacion)) THEN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''CANECAS_VENTA_ANULADA_INMUTABLE''; END IF; END')=1, 'OK', 'DETENER') AS resultado;
SELECT 'trigger trg_can_venta_bd exacto (tiempo, evento, tabla y cuerpo normalizado)' AS verificacion, IF((SELECT COUNT(*) FROM information_schema.TRIGGERS WHERE TRIGGER_SCHEMA='u611730801_Plataforma' AND TRIGGER_NAME='trg_can_venta_bd' AND EVENT_OBJECT_TABLE='canecas_ventas' AND ACTION_TIMING='BEFORE' AND EVENT_MANIPULATION='DELETE' AND BINARY TRIM(REGEXP_REPLACE(REPLACE(ACTION_STATEMENT, CHAR(13), ''), '[[:space:]]+', ' '))=BINARY 'BEGIN SIGNAL SQLSTATE ''45000'' SET MESSAGE_TEXT = ''CANECAS_VENTA_NO_ELIMINABLE''; END')=1, 'OK', 'DETENER') AS resultado;
